namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public int TotalRating { get; set; }
    public int RatingCount { get; set; }

    public double AverageRating => RatingCount > 0 ? (double)TotalRating / RatingCount : 0;
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="star-rating">
    <span class="rating-label">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              title="@star star(s)">★</span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

<div class="average-rating">
    @if (_recipe?.RatingCount > 0)
    {
        <span>Average: @_recipe.AverageRating.ToString("F1") / 5 (@_recipe.RatingCount ratings)</span>
    }
    else
    {
        <span>No ratings yet. Be the first!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private Models.Recipe? _recipe;
    private int _selectedRating;
    private bool _submitted;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(RecipeId);
    }

    private void Rate(int stars)
    {
        _selectedRating = stars;
        RecipeService.RateRecipe(RecipeId, stars);
        _recipe = RecipeService.GetById(RecipeId);
        _submitted = true;
    }
}

@page "/"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>RecipeShare - Home</PageTitle>

<h1>🍳 Welcome to RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2>Browse by Category</h2>
<div class="categories-grid">
    @foreach (var category in RecipeService.GetCategories())
    {
        <a href="/recipes/@category.ToLower()" class="category-card">
            <div class="category-icon">@GetCategoryIcon(category)</div>
            <h3>@category</h3>
            <p>@RecipeService.GetByCategory(category).Count recipes</p>
        </a>
    }
</div>

@code {
    private static string GetCategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

@page "/recipes/{Category}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@Category Recipes - RecipeShare</PageTitle>

<h1>@Category Recipes</h1>

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in recipes)
        {
            <a href="/recipe/@recipe.Id" class="recipe-card">
                <h3>@recipe.Title</h3>
                @if (recipe.RatingCount > 0)
                {
                    <span class="recipe-rating">★ @recipe.AverageRating.ToString("F1")</span>
                }
            </a>
        }
    </div>
}

<a href="/" class="back-link">← Back to categories</a>

@code {
    [Parameter] public string Category { get; set; } = string.Empty;

    private IReadOnlyList<Models.Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@using RecipeShare.Components.Shared
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <h1>@recipe.Title</h1>
    <span class="recipe-category-badge">@recipe.Category</span>

    <h2>Ingredients</h2>
    <ul class="ingredients-list">
        @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h2>Steps</h2>
    <div class="steps-list">
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <p>@step</p>
        }
    </div>

    <h2>Rating</h2>
    <StarRating RecipeId="@recipe.Id" />
}

<a href="/" class="back-link">← Back to categories</a>

@code {
    [Parameter] public int Id { get; set; }

    private Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="success-message">
        <p>✅ Your recipe "<strong>@_model.Title</strong>" has been submitted successfully!</p>
        <a href="/recipe/@_submittedId">View your recipe</a>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />

        <div class="form-group">
            <label for="title">Recipe Title</label>
            <InputText id="title" @bind-Value="_model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <InputSelect id="category" @bind-Value="_model.Category" class="form-control">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" class="form-control" rows="6"
                placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => _model.Ingredients" />
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="_model.Steps" class="form-control" rows="6"
                placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. Add wet ingredients" />
            <ValidationMessage For="() => _model.Steps" />
        </div>

        <button type="submit" class="btn-submit">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel _model = new();
    private bool _submitted;
    private int _submittedId;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = _model.Title,
            Category = _model.Category,
            Ingredients = _model.Ingredients,
            Steps = _model.Steps
        };
        RecipeService.AddRecipe(recipe);
        _submittedId = recipe.Id;
        _submitted = true;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required")]
        public string Steps { get; set; } = string.Empty;
    }
}

