{"file_text": "using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes over dough.\n4. Tear mozzarella and distribute evenly.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle with olive oil." },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper", Steps = "1. Cook spaghetti in salted water until al dente.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, stir in egg mixture.\n6. Serve immediately with extra pecorino." },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTurmeric\nCanned tomatoes\nHeavy cream\nGarlic\nGinger\nOnion", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomatoes and simmer 15 minutes.\n5. Stir in cream and grilled chicken.\n6. Simmer 10 minutes and serve with rice." },
        new Recipe { Id = 4, Title = "Vegetable Biryani", Category = "Indian", Ingredients = "Basmati rice\nMixed vegetables\nOnions\nYogurt\nBiryani masala\nSaffron\nMint\nCilantro\nGhee", Steps = "1. Soak rice for 30 minutes, then parboil.\n2. Fry sliced onions until golden.\n3. Layer vegetables, rice, and fried onions in pot.\n4. Add saffron milk and herbs.\n5. Seal and cook on low heat for 25 minutes.\n6. Fluff gently and serve with raita." },
        new Recipe { Id = 5, Title = "Tacos al Pastor", Category = "Mexican", Ingredients = "Pork shoulder\nPineapple\nDried chiles\nAchiote paste\nCorn tortillas\nOnion\nCilantro\nLime", Steps = "1. Blend dried chiles with achiote and pineapple juice.\n2. Marinate sliced pork overnight.\n3. Grill pork and pineapple slices.\n4. Chop pork and pineapple into small pieces.\n5. Warm tortillas on a comal.\n6. Serve topped with onion, cilantro, and lime." },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nOnion\nJalapeño\nTomato\nSalt", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Dice onion, tomato, and jalapeño.\n4. Fold in diced vegetables and cilantro.\n5. Season with lime juice and salt.\n6. Serve immediately with tortilla chips." },
        new Recipe { Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract", Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs and sugar until fluffy.\n3. Fold chocolate mixture into eggs.\n4. Add flour and vanilla, fold gently.\n5. Pour into greased ramekins.\n6. Bake at 425°F for 12-14 minutes.\n7. Invert onto plate and serve immediately." },
        new Recipe { Id = 8, Title = "Tiramisu", Category = "Desserts", Ingredients = "Ladyfingers\nMascarpone\nEggs\nSugar\nEspresso\nCocoa powder\nMarsala wine", Steps = "1. Brew espresso and let cool, add Marsala.\n2. Separate eggs; whisk yolks with sugar.\n3. Fold in mascarpone until smooth.\n4. Whip egg whites to stiff peaks, fold in.\n5. Dip ladyfingers briefly in espresso.\n6. Layer ladyfingers and cream in dish.\n7. Refrigerate 4+ hours, dust with cocoa." },
    };

    private int _nextId = 9;

    public IReadOnlyList<Recipe> GetAll() => _recipes.AsReadOnly();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().ToList();

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void RateRecipe(int id, int stars)
    {
        var recipe = GetById(id);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalRating += stars;
            recipe.RatingCount++;
        }
    }
}
